  var ALL_VOCAB = RAW_DATA;

  // 1. Chuyển đổi Katakana về Hiragana
  ALL_VOCAB.toHiragana = function(str) {
    if (!str) return '';
    return str.replace(/[\u30a1-\u30f6]/g, function(match) {
      return String.fromCharCode(match.charCodeAt(0) - 0x60);
    });
  };

  // 2. Lấy âm Kana đầu tiên
  ALL_VOCAB.getFirstKana = function(wordOrItem) {
    var text = (typeof wordOrItem === 'object' && wordOrItem) ? (wordOrItem.hiragana || wordOrItem.w) : String(wordOrItem);
    var hira = ALL_VOCAB.toHiragana(text);
    return hira ? hira.charAt(0) : '';
  };

  // 3. Lấy âm Kana cuối cùng (xử lý trường âm ー và âm nhỏ)
  ALL_VOCAB.getLastKana = function(wordOrItem) {
    var text = (typeof wordOrItem === 'object' && wordOrItem) ? (wordOrItem.hiragana || wordOrItem.w) : String(wordOrItem);
    var hira = ALL_VOCAB.toHiragana(text);
    if (!hira) return '';
    
    var lastChar = hira.charAt(hira.length - 1);
    if (lastChar === 'ー' && hira.length > 1) {
      lastChar = hira.charAt(hira.length - 2);
    }
    
    var smallToBig = {
      'ゃ': 'や', 'ゅ': 'ゆ', 'ょ': 'よ',
      'ぁ': 'あ', 'ぃ': 'い', 'ぅ': 'う', 'ぇ': 'え', 'ぉ': 'お',
      'っ': 'つ'
    };
    return smallToBig[lastChar] || lastChar;
  };

  // 4. Kiểm tra luật cấm Shiritori: kết thúc bằng âm 'ん'
  ALL_VOCAB.isShiritoriLoss = function(wordOrItem) {
    var last = ALL_VOCAB.getLastKana(wordOrItem);
    return last === 'ん';
  };

  // 5. Tìm từ theo từ khóa
  ALL_VOCAB.findByWord = function(keyword, levelFilter) {
    if (!keyword) return null;
    var q = keyword.toLowerCase().trim();
    // Ưu tiên khớp chính xác theo Kanji, Hiragana, w, hoặc Romaji
    var exact = ALL_VOCAB.find(function(item) {
      if (levelFilter && levelFilter !== 'ALL' && item.level !== levelFilter) return false;
      return item.kanji === keyword ||
             item.hiragana === keyword ||
             item.w === keyword ||
             (item.romaji && item.romaji.toLowerCase() === q);
    });
    if (exact) return exact;
    // Khớp mềm theo nghĩa
    return ALL_VOCAB.find(function(item) {
      if (levelFilter && levelFilter !== 'ALL' && item.level !== levelFilter) return false;
      return item.meaning && item.meaning.toLowerCase().indexOf(q) !== -1;
    }) || null;
  };

  // 6. Lọc từ theo cấp độ
  ALL_VOCAB.filterByLevel = function(level) {
    if (!level || level === 'ALL') return ALL_VOCAB;
    return ALL_VOCAB.filter(function(item) {
      return item.level === level;
    });
  };

  // 7. Lấy danh sách ứng viên Shiritori
  ALL_VOCAB.getShiritoriCandidates = function(lastKana, usedSet, levelFilter, categoryFilter) {
    var target = ALL_VOCAB.toHiragana(lastKana);
    return ALL_VOCAB.filter(function(item) {
      if (levelFilter && levelFilter !== 'ALL' && item.level !== levelFilter) return false;
      if (categoryFilter && categoryFilter !== 'ALL' && item.category !== categoryFilter) return false;
      var first = ALL_VOCAB.getFirstKana(item);
      if (first !== target) return false;
      if (usedSet) {
        var isUsed = false;
        if (typeof usedSet.has === 'function') {
          isUsed = usedSet.has(item.kanji) || usedSet.has(item.hiragana) || usedSet.has(item.w) || usedSet.has(item.id);
        } else if (Array.isArray(usedSet)) {
          isUsed = usedSet.indexOf(item.kanji) !== -1 || usedSet.indexOf(item.hiragana) !== -1 || usedSet.indexOf(item.w) !== -1;
        } else {
          isUsed = !!(usedSet[item.kanji] || usedSet[item.hiragana] || usedSet[item.w] || usedSet[item.id]);
        }
        if (isUsed) return false;
      }
      return true;
    });
  };

  // 8. Bot AI trả lời Shiritori
  ALL_VOCAB.getBotShiritoriReply = function(lastKana, usedSet, levelFilter, categoryFilter) {
    var candidates = ALL_VOCAB.getShiritoriCandidates(lastKana, usedSet, levelFilter, categoryFilter);
    if (!candidates || candidates.length === 0) return null;
    
    var safeWords = candidates.filter(function(item) {
      return !ALL_VOCAB.isShiritoriLoss(item);
    });
    
    var pool = (safeWords.length > 0) ? safeWords : candidates;
    var randomIndex = Math.floor(Math.random() * pool.length);
    return pool[randomIndex];
  };

  // 9. Lấy ngẫu nhiên N từ
  ALL_VOCAB.getRandomWords = function(count, levelFilter, categoryFilter) {
    var pool = ALL_VOCAB;
    if (levelFilter && levelFilter !== 'ALL') {
      pool = pool.filter(function(x) { return x.level === levelFilter; });
    }
    if (categoryFilter && categoryFilter !== 'ALL') {
      pool = pool.filter(function(x) { return x.category === categoryFilter; });
    }
    var shuffled = pool.slice().sort(function() { return 0.5 - Math.random(); });
    return shuffled.slice(0, count || 1);
  };

  // 10. Danh sách tất cả chủ đề duy nhất
